using Microsoft.Extensions.Options;using TuoiTho.Core.Policy;using TuoiTho.Storage;
namespace TuoiTho.Service;
public sealed class M1BootstrapOptions{public const string SectionName="M1Bootstrap";public bool Enabled{get;init;}public string ProfileId{get;init;}="m1-child";public int ManagedSessionId{get;init;}public string ManagedUserSid{get;init;}="";public int QuotaMinutes{get;init;}=3;}
public sealed class M1Bootstrapper(SqliteDatabase database,IDeviceTimePolicyStore store,IOptions<M1BootstrapOptions> options,PolicyChangeSignal signal):IHostedService
{public async Task StartAsync(CancellationToken cancellationToken){await database.InitializeAsync(cancellationToken);var o=options.Value;if(!o.Enabled)return;if(o.ManagedSessionId<0||string.IsNullOrWhiteSpace(o.ManagedUserSid))throw new InvalidOperationException("M1 bootstrap requires current session and SID.");var windows=Enum.GetValues<DayOfWeek>().Select(day=>new AllowedUsageWindow(day,TimeOnly.MinValue,new TimeOnly(23,59))).ToArray();await store.SaveAsync(new DeviceTimePolicy(o.ProfileId,o.ManagedSessionId,o.QuotaMinutes,windows,DeviceTimePolicy.DefaultWarnings,false,false,true){ManagedUserSid=o.ManagedUserSid},cancellationToken);signal.Notify();}public Task StopAsync(CancellationToken cancellationToken)=>Task.CompletedTask;}
